-- Isolated PostgreSQL test fixture, never production setup.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
create function auth.jwt() returns jsonb language sql stable as $$ select jsonb_build_object('role', current_setting('request.jwt.claim.role', true)) $$;
create table auth.users(id uuid primary key, email text);
create table public.profiles(id uuid primary key references auth.users, email text, last_seen timestamptz, created_at timestamptz default now());
create table public.app_admins(email text primary key);
create function public.is_admin() returns boolean language sql stable security definer as $$ select exists(select 1 from auth.users u where u.id = auth.uid() and (u.email = 'owner@example.test' or exists(select 1 from app_admins a where a.email=u.email))) $$;
create function public.is_job_sites_admin() returns boolean language sql stable security definer as $$ select public.is_admin() $$;
create table public.entitlements(user_id uuid primary key references auth.users, tier text default 'free', plan text, expires_at timestamptz, source text, discount_pct int default 0, discount_expires_at timestamptz, issued_by uuid, addons jsonb not null default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.grant_codes(id bigint generated always as identity primary key, code text unique, plan text default 'monthly', valid_days int default 30, discount_pct int default 0, created_by uuid, created_at timestamptz default now(), expires_at timestamptz, used_by uuid, used_at timestamptz);
create table public.payments(user_id uuid, provider text, provider_payment_id text unique, plan text, amount_minor int, currency text, discount_pct int, status text, kind text);
create table public.billing_actions(admin_id uuid, action text, user_id uuid, detail jsonb);
create function public.log_billing_action(p_action text,p_user uuid,p_detail jsonb) returns void language sql security definer as $$ insert into public.billing_actions values(auth.uid(),p_action,p_user,p_detail) $$;
create function public.plan_days(p_plan text) returns int language sql immutable as $$ select case p_plan when 'monthly' then 30 when 'yearly' then 365 else null end $$;
create table public.job_sites(id uuid primary key default gen_random_uuid(), host text unique, label text, jobs_url text, source text, status text, rules jsonb default '{}');
create table public.apply_config(id text primary key, mode text,cloud_provider text,cloud_endpoint text,updated_at timestamptz,policy_daily_cap int,policy_weekly_cap int,policy_daily_cap_per_employer int,policy_weekly_cap_per_employer int,policy_quiet_from text,policy_quiet_to text,policy_filters jsonb);
create function public.admin_get_apply_config() returns table(mode text,cloud_provider text,cloud_endpoint text,updated_at timestamptz) language sql security definer as $$ select mode,cloud_provider,cloud_endpoint,updated_at from apply_config $$;
create table public.apply_results(id uuid primary key default gen_random_uuid(),site_host text not null,job_url text not null,title text,company text,result text not null,detail text,fit int,posted_age_h int check(posted_age_h>=0),feedback text,created_at timestamptz default now());
create table public.job_apply_reviews(id uuid primary key default gen_random_uuid(),site_host text not null,job_url text not null,title text,company text,form_url text,status text default 'pending',reason text,fit int,form_fields jsonb,posted_age_h int check(posted_age_h>=0),created_at timestamptz default now(),resolved_at timestamptz,unique(site_host,job_url));
create table public.apply_resume_variants(id uuid primary key default gen_random_uuid(),site_host text,job_url text not null,title text,company text,master_text text,variant_text text,diff_summary jsonb,variant_id text not null,approved boolean default false,created_at timestamptz default now(),approved_at timestamptz);
create table public.form_answers(id uuid primary key default gen_random_uuid(),site_host text not null,field_key text not null,answer text not null,kind text,label text,source text default 'engine',updated_at timestamptz default now(),reuse_count int not null default 0,last_used_at timestamptz,unique(site_host,field_key));
create table public.apply_skill_strikes(site_host text not null,skill text not null,strikes int default 0,updated_at timestamptz default now(),unique(site_host,skill));
create table public.judge_exemplars(id uuid primary key default gen_random_uuid(),kind text not null,summary text not null,reason text,source_url text,created_at timestamptz default now());
create table public.apply_outcomes(id uuid primary key default gen_random_uuid(),site_host text not null,job_url text not null unique,fit int,fit_band text default 'unknown',viewed_at timestamptz,responded_at timestamptz,response_kind text,detail text,scraped_at timestamptz default now());
create table public.user_notify_config(user_id uuid primary key references auth.users,chat_id text,bot_token text,updated_at timestamptz default now());
alter table public.user_notify_config enable row level security;
create function public.review_posting_key(p_url text) returns text language sql immutable as $$ select lower(regexp_replace(split_part(p_url,'?',1),'/+$','')) $$;
create function public.fit_band_of(fit int) returns text language sql immutable as $$ select case when fit is null then 'unknown' when fit>=85 then '85+' when fit>=70 then '70-84' when fit>=50 then '50-69' else '<50' end $$;
grant usage on schema public,auth to authenticated,anon,service_role;
grant execute on all functions in schema auth to authenticated,anon,service_role;
